(function(){
'use strict';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let loading=false,saving=false;
let pendingRpeAuthoritative=[];
const db=()=>window.VolleySupabase?.getClient?.()||null;
const state=()=>typeof appState!=='undefined'?appState:null;
const call=(n,...a)=>{try{if(typeof window[n]==='function')window[n](...a)}catch(_){}};
function ev(id){const s=state();if(!s)return null;const x=String(id||'');return(s.events||[]).find(e=>[e.id,e.supabaseId,e.supabase_id,e.legacy_id,e.legacyId].filter(Boolean).map(String).includes(x))||null;}
function pl(id){const s=state();if(!s)return null;const x=String(id||'');return(s.players||[]).find(p=>[p.id,p.supabaseId,p.legacy_id,p.legacyId,p.profile_id].filter(Boolean).map(String).includes(x))||null;}
function isTraining(e){const t=String(e?.event_type||e?.eventType||e?.type||e?.payload?.type||e?.rawPayload?.type||e?.title||'').toLowerCase();return t==='training'||t.includes('entrenamiento');}
function endTime(e){if(!e)return null;if(e.ends_at||e.endsAt){const d=new Date(e.ends_at||e.endsAt);if(!Number.isNaN(d.getTime()))return d;}const starts=e.starts_at||e.startsAt;if(starts){const d=new Date(starts);const mins=Number(e.payload?.duration??e.rawPayload?.duration??e.duration);if(!Number.isNaN(d.getTime())&&Number.isFinite(mins)&&mins>0)return new Date(d.getTime()+mins*60000);}if(e.date){const start=new Date(`${e.date}T${e.time||'00:00'}:00`);const mins=Number(e.duration||e.rawPayload?.duration||120);if(!Number.isNaN(start.getTime()))return new Date(start.getTime()+mins*60000);}return null;}
function currentPlayer(){try{const u=getCurrentUser?.();if(!u?.playerId&&!u?.supabasePlayerId)return null;return pl(u.playerId)||pl(u.supabasePlayerId)}catch(_){return null;}}
function normalizePendingEvent(row){const local=ev(row.id)||ev(row.legacy_id);return Object.assign({},local||{},row,{id:local?.id||row.id,supabaseId:row.id,supabase_id:row.id,legacy_id:row.legacy_id||local?.legacy_id||local?.legacyId||null,legacyId:row.legacy_id||local?.legacyId||local?.legacy_id||null,rawPayload:local?.rawPayload||row.payload||{},payload:row.payload||local?.payload||local?.rawPayload||{}});}
function setPendingCache(items){pendingRpeAuthoritative=Array.isArray(items)?items:[];const s=state();if(s){s.pendingRpeEventIds=pendingRpeAuthoritative.map(e=>e.id);s.pendingRpeSupabaseEventIds=pendingRpeAuthoritative.map(e=>e.supabaseId||e.supabase_id||e.id);}}
function pendingForCurrentPlayer(){return pendingRpeAuthoritative.slice();}
function removeLegacyPendingRpeNotices(){const root=document.getElementById('home-dashboard');if(!root)return;const selectors='.dashboard-action-card,.dashboard-card,.home-dashboard-card,.dashboard-alert,.player-home-card,[data-rpe-pending]';root.querySelectorAll(selectors).forEach(card=>{if(card.id==='rpe-pending-authoritative')return;const txt=String(card.textContent||'').toLowerCase();if(txt.includes('rpe')&&(txt.includes('te falta')||txt.includes('pendiente')||txt.includes('enviar el rpe')))card.style.display='none';});}
function paintPendingNotice(){const root=document.getElementById('home-dashboard');if(!root)return;removeLegacyPendingRpeNotices();let card=document.getElementById('rpe-pending-authoritative');const u=(()=>{try{return getCurrentUser?.()}catch(_){return null}})();if(!u?.playerId&&!u?.supabasePlayerId){card?.remove();return;}const pending=pendingForCurrentPlayer();if(!pending.length){card?.remove();return;}const latest=pending[0];if(!card){card=document.createElement('button');card.type='button';card.id='rpe-pending-authoritative';card.className='rpe-pending-authoritative';root.prepend(card);}card.onclick=()=>{call('openModule','training',{returnTarget:'home-portal'});setTimeout(()=>call('openSessionCenter',latest.id,'home-portal'),0);};card.innerHTML=`<span class="rpe-pending-icon">!</span><span><strong>Te falta enviar el RPE del entrenamiento</strong><small>${pending.length>1?`Tienes ${pending.length} sesiones pendientes.`:'La sesión ya ha terminado. Registra tu percepción del esfuerzo.'}</small></span><span class="rpe-pending-arrow">›</span>`;}
function injectPendingCss(){if(document.getElementById('rpe-pending-authoritative-css'))return;const s=document.createElement('style');s.id='rpe-pending-authoritative-css';s.textContent=`.rpe-pending-authoritative{width:100%;display:flex;align-items:center;gap:.8rem;text-align:left;border:1px solid #fed7aa;background:#fff7ed;color:#9a3412;border-radius:14px;padding:.9rem 1rem;margin:0 0 1rem;cursor:pointer}.rpe-pending-authoritative strong{display:block;font-size:.92rem}.rpe-pending-authoritative small{display:block;color:#78716c;margin-top:.15rem}.rpe-pending-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#f97316;color:white;font-weight:900;flex:none}.rpe-pending-arrow{margin-left:auto;font-size:1.6rem;color:#f97316}`;document.head.appendChild(s);}
async function eventUuid(id){const c=db(),e=ev(id);if(!c)return null;for(const v of[e?.id,e?.supabaseId,e?.supabase_id,id])if(UUID.test(String(v||'')))return String(v);const legacy=e?.legacy_id||e?.legacyId||id;const{data,error}=await c.from('events').select('id').eq('legacy_id',String(legacy)).maybeSingle();if(error)throw error;return data?.id||null;}
async function syncPlayers(){const c=db(),s=state();if(!c||!s)return;const{data,error}=await c.from('players').select('id,legacy_id,profile_id,active,profiles:profile_id(username)');if(error)throw error;for(const r of data||[]){if(r.active===false)continue;const p=(s.players||[]).find(x=>String(x.supabaseId||'')===r.id||String(x.id||'')===String(r.legacy_id||'')||String(x.legacy_id||x.legacyId||'')===String(r.legacy_id||'')||String(x.username||'').toLowerCase()===String(r.profiles?.username||'').toLowerCase());if(p){p.supabaseId=r.id;p.legacy_id=r.legacy_id||p.legacy_id;p.profile_id=r.profile_id||p.profile_id;}}}
async function syncPendingRpeFromSupabase(rpeRows=[]){const c=db();if(!c){setPendingCache([]);return[];}let ident;try{ident=await window.VolleySupabase.getIdentity();}catch(_){setPendingCache([]);return[];}const pid=ident?.data?.player?.id;if(!UUID.test(String(pid||''))){setPendingCache([]);return[];}const{data:events,error}=await c.from('events').select('id,legacy_id,event_type,title,starts_at,ends_at,status,payload');if(error){setPendingCache([]);throw error;}const answered=new Set((rpeRows||[]).filter(r=>String(r.player_id||'')===String(pid)&&UUID.test(String(r.event_id||''))).map(r=>String(r.event_id)));
const now=Date.now();const pending=(events||[]).filter(row=>{if(!isTraining(row))return false;const end=endTime(row);return !!(end&&end.getTime()<=now&&!answered.has(String(row.id)));}).map(normalizePendingEvent).sort((a,b)=>(endTime(b)?.getTime()||0)-(endTime(a)?.getTime()||0));setPendingCache(pending);return pending;}
function forgetPendingEvent(eventId){const x=String(eventId||'');setPendingCache(pendingRpeAuthoritative.filter(e=>![e.id,e.supabaseId,e.supabase_id,e.legacy_id,e.legacyId].filter(Boolean).map(String).includes(x)));setTimeout(paintPendingNotice,0);}
async function load(opts={}){if(loading)return;const c=db(),s=state();if(!c||!s)return;loading=true;try{await syncPlayers();const{data,error}=await c.from('rpe_entries').select('id,event_id,player_id,coach_profile_id,score,source,created_at');if(error)throw error;s.trainingRPEs=[];for(const e of s.events||[]){delete e.rpe;e.coachRpe=NaN;e.coachRPE=NaN;}for(const r of data||[]){const e=ev(r.event_id);if(!e)continue;if(r.source==='coach'){e.coachRpe=Number(r.score);e.coachRPE=Number(r.score);continue;}const p=pl(r.player_id);if(!p)continue;s.trainingRPEs.push({id:r.id,eventId:e.id,playerId:p.id,rpeVal:Number(r.score),addedByCoach:r.source==='coach_for_player',source:r.source,supabaseEventId:r.event_id,supabasePlayerId:r.player_id});}try{await syncPendingRpeFromSupabase(data||[]);}catch(e){console.warn('[RPE] No se pudo sincronizar el aviso pendiente:',e);}if(!opts.silent){call('renderTraining');call('renderHomeDashboard');call('renderTeamRpeSummary');call('renderSessionCenterDetail');}setTimeout(paintPendingNotice,0);return data||[];}finally{loading=false;}}
async function savePlayer(eventId,score){const c=db();if(!c||saving)return;saving=true;try{const eid=await eventUuid(eventId),ident=await window.VolleySupabase.getIdentity(),pid=ident?.data?.player?.id;if(!UUID.test(String(eid||''))||!UUID.test(String(pid||'')))throw new Error('No se encuentra la sesión o la jugadora.');const{data:e,error:ee}=await c.from('events').select('event_type,ends_at,starts_at,payload').eq('id',eid).single();if(ee)throw ee;if(!isTraining(e))throw new Error('El RPE solo se puede registrar en entrenamientos.');const end=endTime(e);if(!end||end>new Date())throw new Error('Podrás enviar el RPE cuando haya terminado el entrenamiento.');const{data:old,error:oe}=await c.from('rpe_entries').select('id').eq('event_id',eid).eq('player_id',pid).maybeSingle();if(oe)throw oe;if(old){forgetPendingEvent(eid);await load({silent:true});throw new Error('Tu RPE ya está registrado.');}const{error}=await c.from('rpe_entries').insert({event_id:eid,player_id:pid,score:Number(score),source:'player'});if(error)throw error;forgetPendingEvent(eid);await load({silent:true});call('renderTraining');call('renderHomeDashboard');call('renderSessionCenterDetail');setTimeout(paintPendingNotice,0);showToast?.(`Esfuerzo registrado: ${score}/10`);}catch(e){showToast?.(e.message||'No se pudo guardar el RPE.','error');}finally{saving=false;}}
async function saveCoach(eventId,score){const c=db();if(!c||saving)return;saving=true;try{const eid=await eventUuid(eventId),ident=await window.VolleySupabase.getIdentity(),cid=ident?.data?.profile?.id;if(!UUID.test(String(eid||''))||!UUID.test(String(cid||'')))throw new Error('No se encuentra la sesión o el entrenador.');const{data:old}=await c.from('rpe_entries').select('id').eq('event_id',eid).eq('coach_profile_id',cid).maybeSingle();if(old)throw new Error('Tu valoración ya está registrada.');const{error}=await c.from('rpe_entries').insert({event_id:eid,coach_profile_id:cid,player_id:null,score:Number(score),source:'coach'});if(error)throw error;await load({silent:true});call('renderTraining');call('renderHomeDashboard');call('renderSessionCenterDetail');showToast?.(`Valoración registrada: ${score}/10`);}catch(e){showToast?.(e.message||'No se pudo guardar la valoración.','error');}finally{saving=false;}}
async function saveForPlayer(eventId,playerId){const sel=document.getElementById(`coach-rpe-${eventId}-${playerId}`),score=Number(sel?.value),c=db();if(!c||saving||!Number.isFinite(score))return;saving=true;try{await syncPlayers();const eid=await eventUuid(eventId),p=pl(playerId),pid=p?.supabaseId;if(!UUID.test(String(eid||''))||!UUID.test(String(pid||'')))throw new Error('No se encuentra la jugadora.');const{data:old}=await c.from('rpe_entries').select('id,source').eq('event_id',eid).eq('player_id',pid).maybeSingle();if(old)throw new Error(old.source==='player'?'La jugadora ya ha contestado su RPE.':'Ese RPE ya está registrado.');const{error}=await c.from('rpe_entries').insert({event_id:eid,player_id:pid,score,source:'coach_for_player'});if(error)throw error;await load({silent:true});call('renderTraining');call('renderTeamRpeSummary');call('renderSessionCenterDetail');showToast?.('RPE añadido correctamente.');}catch(e){showToast?.(e.message||'No se pudo guardar el RPE.','error');}finally{saving=false;}}
function install(){const wait=()=>{if(!window.VolleySupabase||typeof window.setTrainingRPE!=='function'){setTimeout(wait,200);return;}injectPendingCss();window.loadRpeFromSupabase=load;window.getPendingRpeEvents=()=>pendingForCurrentPlayer().slice();window.isRpeSubmissionWindowOpen=e=>{const end=endTime(e);return !!(e&&end&&end<=new Date());};window.setTrainingRPE=(eventId,val,mode=null)=>{const u=getCurrentUser?.();const coach=mode==='coach'||(!u?.playerId&&isCoachUser?.());return coach?saveCoach(eventId,val):savePlayer(eventId,val);};window.addPlayerRpeByCoach=saveForPlayer;const baseRender=window.renderHomeDashboard;if(typeof baseRender==='function'&&!baseRender.__rpeAuthoritativeWrapped){const wrapped=function(){const out=baseRender.apply(this,arguments);setTimeout(paintPendingNotice,0);return out;};wrapped.__rpeAuthoritativeWrapped=true;window.renderHomeDashboard=wrapped;}void load({silent:false});const c=db();c?.channel('rpe-authoritative-live').on('postgres_changes',{event:'*',schema:'public',table:'rpe_entries'},()=>void load({silent:false})).subscribe();setInterval(()=>void load({silent:true}),5000);};setTimeout(wait,1400);}install();
})();
